const dayDef = (weekday, focusKey, tagLabel, list) => ({ id: uid(), weekday, focusKey, tagLabel, list });

const reorder = (arr, from, to) => {
  const next = [...arr];
  const [moved] = next.splice(from, 1);
  next.splice(to, 0, moved);
  return next;
};

// Busca, entre los nodos registrados (key -> elemento DOM), el más cercano a un punto x/y.
const nearestKeyByPosition = (nodesMap, x, y) => {
  let best = null;
  let bestDist = Infinity;
  Object.keys(nodesMap).forEach((key) => {
    const node = nodesMap[key];
    if (!node) return;
    const rect = node.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const dist = Math.hypot(cx - x, cy - y);
    if (dist < bestDist) { bestDist = dist; best = key; }
  });
  return best;
};

// Fábrica de manejadores de arrastre por Pointer Events: funciona con mouse, touch y stylus,
// a diferencia del HTML5 drag-and-drop nativo (que no funciona en la mayoría de los navegadores móviles).
const makePointerReorder = ({ nodesRef, dragRef, setDragKey, setOverKey, onDrop }) => (key) => (e) => {
  e.preventDefault();
  const targetEl = e.currentTarget;
  const pointerId = e.pointerId;
  try { targetEl.setPointerCapture(pointerId); } catch (err) { /* algunos navegadores viejos no lo soportan */ }
  dragRef.current = key;
  setDragKey(key);
  setOverKey(key);

  const handleMove = (ev) => {
    ev.preventDefault();
    const nearest = nearestKeyByPosition(nodesRef.current, ev.clientX, ev.clientY);
    if (nearest !== null) setOverKey(nearest);
  };

  const handleUp = (ev) => {
    window.removeEventListener('pointermove', handleMove);
    window.removeEventListener('pointerup', handleUp);
    window.removeEventListener('pointercancel', handleUp);
    try { targetEl.releasePointerCapture(ev.pointerId != null ? ev.pointerId : pointerId); } catch (err) { /* noop */ }
    document.body.style.userSelect = '';
    const fromKey = dragRef.current;
    dragRef.current = null;
    setDragKey(null);
    setOverKey((currentOverKey) => {
      if (fromKey !== null && currentOverKey !== null && fromKey !== currentOverKey) {
        onDrop(fromKey, currentOverKey);
      }
      return null;
    });
  };

  document.body.style.userSelect = 'none';
  window.addEventListener('pointermove', handleMove, { passive: false });
  window.addEventListener('pointerup', handleUp);
  window.addEventListener('pointercancel', handleUp);
};

