// ---------- Historial de entrenamientos ----------
// Cuando alguien marca al menos la mitad de los ejercicios de un día (MIN_DONE_RATIO), se
// guarda un registro en data.history (viaja con el resto de los datos, así que también se
// sincroniza con el código). Si después sigue marcando, el mismo registro se actualiza:
//   { id, date: 'AAAA-MM-DD', startedAt, completedAt, variantId, variantName, color,
//     dayId, weekday, label, doneCount, totalCount, exercises: [{ name, done, target, sets }] }
// startedAt es cuándo se marcó la primera casilla de esa sesión y completedAt la última.
// Cada ejercicio guarda además doneAt (cuándo se tildó) para saber qué se hizo en cada sesión.
// Si entre una casilla y la siguiente pasan más de 12 h, se toma como un entrenamiento nuevo.
const WORKOUT_SESSION_STALE_MS = 12 * 60 * 60 * 1000;
// Qué parte de los ejercicios de un día hay que marcar para que cuente como entrenado (0.5 = la mitad).
const MIN_DONE_RATIO = 0.5;

// Un ejercicio cuenta como hecho en la sesión si se tildó o si tiene al menos una serie anotada.
const isTouched = (e, now) => !!e && (e.done || doneSetsOf(e, now).length > 0);
const touchScore = (e, now) => (e ? (e.done ? 1 : 0) + doneSetsOf(e, now).length : 0);
const countTouched = (d, now) => (d && d.list ? d.list.filter((e) => isTouched(e, now)).length : 0);
const sumScore = (d, now) => (d && d.list ? d.list.reduce((acc, e) => acc + touchScore(e, now), 0) : 0);

// Se llama cada vez que cambia un día de la rutina activa. Devuelve el día (con las horas de
// cada casilla y el inicio de la sesión actualizados) y el historial (con el registro de esta
// sesión agregado, actualizado o quitado según corresponda).
const trackWorkoutProgress = (history, variant, before, after, now = Date.now()) => {
  const prevById = {};
  ((before && before.list) || []).forEach((e) => { prevById[e.id] = e; });
  const list = (after.list || []).map((e) => {
    const prev = prevById[e.id];
    let next = e;
    if (isTouched(e, now) && !isTouched(prev, now)) next = { ...next, doneAt: now };
    if (!isTouched(e, now) && (e.doneAt || e.lastAt)) {
      const { doneAt, lastAt, ...rest } = next;
      next = rest;
    } else if (touchScore(e, now) > touchScore(prev, now)) {
      next = { ...next, lastAt: now };
    }
    return next;
  });
  let day = { ...after, list };

  const doneBefore = countTouched(before, now);
  const doneAfter = countTouched(day, now);
  if (doneAfter === 0) {
    if (day.startedAt) day = { ...day, startedAt: null };
  } else if (sumScore(day, now) > sumScore(before, now)) {
    // Primera casilla, o pasaron más de 12 h desde que arrancó la sesión anterior: sesión nueva.
    const stale = !day.startedAt || now - day.startedAt > WORKOUT_SESSION_STALE_MS;
    if (doneBefore === 0 || stale) day = { ...day, startedAt: now };
  }
  if (!variant) return { day, history };

  const sessionStart = day.startedAt || (before && before.startedAt) || null;
  const existing = sessionStart ? history.find((h) => h.dayId === day.id && h.startedAt === sessionStart) : null;
  // Ejercicios hechos en esta sesión (los tildados antes de que existiera doneAt cuentan igual).
  const sessionDone = day.startedAt
    ? list.filter((e) => isTouched(e, now) && ((e.lastAt || e.doneAt) == null || (e.lastAt || e.doneAt) >= day.startedAt))
    : [];
  const total = list.length;
  const qualifies = total > 0 && sessionDone.length > 0 && sessionDone.length / total >= MIN_DONE_RATIO;

  // Una sesión que terminó hace más de 12 h ya no se toca (sus series viejas ya no están en
  // la rutina, así que recalcularla la dejaría incompleta).
  if (existing && now - existing.completedAt > WORKOUT_SESSION_STALE_MS) return { day, history };

  if (qualifies) {
    const doneIds = new Set(sessionDone.map((e) => e.id));
    const exercises = list.map((e) => {
      const sets = doneIds.has(e.id) ? doneSetsOf(e, now).map((x) => ({ kg: x.kg, reps: x.reps })) : [];
      const base = { name: e.name, done: doneIds.has(e.id), ...(e.sets ? { target: e.sets } : {}) };
      return sets.length ? { ...base, sets } : base;
    });
    const changed = !existing || existing.doneCount !== sessionDone.length || existing.totalCount !== total
      || JSON.stringify(existing.exercises) !== JSON.stringify(exercises);
    if (!changed) return { day, history };
    const colors = FOCUS_COLORS[day.focusKey] || FOCUS_COLORS.comodin;
    const lastCheck = Math.max(...sessionDone.map((e) => e.lastAt || e.doneAt || 0));
    const entry = {
      id: existing ? existing.id : uid(),
      date: localDateKey(day.startedAt),
      startedAt: day.startedAt,
      completedAt: lastCheck > 0 ? lastCheck : now,
      variantId: variant.id,
      variantName: variant.name,
      color: variant.color || colors.accent || '#B33A3A',
      dayId: day.id,
      weekday: day.weekday,
      label: day.tagLabel || translateTag(colors.label, getLang()) || day.weekday,
      doneCount: sessionDone.length,
      totalCount: total,
      exercises,
    };
    return { day, history: existing ? history.map((h) => (h.id === existing.id ? entry : h)) : [...history, entry] };
  }

  // Bajó de la mitad (ej. desmarcó algo tildado sin querer): el registro de esta sesión se
  // quita, pero solo si la sesión es reciente. Desmarcar días después (para arrancar otra
  // semana) no borra entrenamientos viejos.
  if (existing && now - existing.completedAt <= WORKOUT_SESSION_STALE_MS) {
    return { day, history: history.filter((h) => h.id !== existing.id) };
  }
  return { day, history };
};

// Al empezar una semana nueva (lunes) las rutinas se reinician solas: se destildan los
// ejercicios y se borran las series anotadas (el historial y las cargas quedan guardados).
// Y los cambios de ejercicio "solo por hoy" vuelven al original al día siguiente.
const resetDayForNewWeek = (d) => ({
  ...d,
  completionPhrase: null,
  startedAt: null,
  list: (d.list || []).map((e) => {
    const { doneAt, lastAt, log, ...rest } = e;
    return { ...rest, done: false };
  }),
});

const revertTodaySwap = (e, todayKey) => {
  if (!e.swappedFrom || e.swappedFrom.date === todayKey) return e;
  const { swappedFrom, log, ...rest } = e;
  return { ...rest, name: swappedFrom.name };
};

const rolloverData = (data, now = Date.now()) => {
  if (!data || !Array.isArray(data.variants)) return data;
  const week = weekKeyOf(now);
  const today = localDateKey(now);
  let changed = false;
  let variants = data.variants.map((v) => ({
    ...v,
    days: (v.days || []).map((d) => {
      const kept = (d.list || []).filter((e) => !e.tempDate || e.tempDate === today);
      const list = kept.map((e) => revertTodaySwap(e, today));
      if (kept.length !== (d.list || []).length || list.some((e, i) => e !== kept[i])) { changed = true; return { ...d, list }; }
      return d;
    }),
  }));
  if (data.weekKey && data.weekKey !== week) {
    variants = variants.map((v) => ({ ...v, days: (v.days || []).map(resetDayForNewWeek) }));
    changed = true;
  }
  if (!changed && data.weekKey === week) return data;
  return { ...data, variants, weekKey: week };
};

const STORAGE_KEY = 'gym-routine-v5';
// Shim de almacenamiento: en Claude.ai esto lo resuelve window.storage (persistencia
// por usuario). Aca, para un deploy normal en Vercel, usamos localStorage del navegador
// (persistencia por dispositivo/navegador, no sincroniza entre dispositivos).
const storage = {
  async get(key) {
    try {
      const value = localStorage.getItem(key);
      return value !== null ? { key, value } : null;
    } catch (e) {
      return null;
    }
  },
  async set(key, value) {
    try {
      localStorage.setItem(key, value);
      return { key, value };
    } catch (e) {
      return null;
    }
  },
};

const API_KEY_STORAGE = 'groq-api-key-v1';
const CHAT_STORAGE = 'joes-chat-v1';
const NUDGE_STORAGE = 'joes-nudge-v1';
const SYNC_CODE_STORAGE = 'sync-code-v1';

// ---------- IA de Joe's (Groq o Google Gemini) ----------
// Cada persona pega su propia API key gratuita, de Groq o de Gemini, y la app reconoce sola de
// cuál es por cómo empieza (ver detectAiProvider). La key se sigue guardando bajo
// API_KEY_STORAGE ('groq-api-key-v1') para no perder las que ya estaban cargadas.
//
// Los dos servicios retiran modelos cada tanto (Groq sacó llama-3.3-70b-versatile del plan
// gratis el 16/08/2026 y eso rompió el chat). Para no depender de un solo nombre de modelo:
//   1. Se prueba con el primero de la lista "preferred" del servicio.
//   2. Si el servicio responde que ese modelo ya no existe, la app le pide la lista de modelos
//      activos, elige el mejor disponible, lo recuerda y reintenta sola.
//   3. Si responde que se llegó al límite gratis de ese modelo, prueba con el otro preferido
//      (en los dos servicios los límites gratis van por modelo).
//   4. Cada 7 días se vuelve a probar el preferido, por si el cambio había sido temporal.
// Si algún día querés forzar otro modelo, alcanza con ponerlo primero en su lista.
const MODEL_RECHECK_MS = 7 * 24 * 60 * 60 * 1000;

const GROQ_BASE_URL = 'https://api.groq.com/openai/v1';
const GROQ_PREFERRED_MODELS = ['openai/gpt-oss-120b', 'openai/gpt-oss-20b'];
// Modelos de la lista de Groq que no sirven para chatear (audio, moderación, etc).
const GROQ_NON_CHAT_PATTERN = /whisper|tts|orpheus|playai|guard|safeguard|embed|compound|allam|distil|vision/i;

const GEMINI_BASE_URL = 'https://generativelanguage.googleapis.com/v1beta';
// Los "-latest" son alias que Google apunta solo al modelo más nuevo de cada línea. Flash-Lite
// va primero porque en el plan gratis permite bastantes más mensajes por día que Flash.
const GEMINI_PREFERRED_MODELS = ['gemini-flash-lite-latest', 'gemini-flash-latest'];
// Modelos de la lista de Gemini que no sirven para chatear o no son gratis.
const GEMINI_NON_CHAT_PATTERN = /tts|image|live|embed|transcribe|translate|audio|robotics|computer|native|aqa|omni|banana|preview|exp|learnlm|pro|argon/i;
// Cuántos mensajes previos del chat se le mandan a Joe's en cada pedido. El plan gratis de
// Groq tiene un tope de tokens por minuto, y mandar la charla entera hace que las
// conversaciones largas terminen fallando.
const CHAT_HISTORY_LIMIT = 20;

const TAB_ORDER = ['routines', 'progress', 'chat', 'profile'];
const EMPTY_PROFILE = { name: '', height: '', weight: '', yearsTraining: '', goal: GOAL_KEYS[0], notes: '' };

// Si el título no fue personalizado a mano, y hay un nombre cargado en el perfil, se usa "Rutina de X".
const getDisplayTitle = (d) => {
  if (d.title && !isDefaultTitle(d.title)) return d.title;
  if (d.profile && d.profile.name) return tr('titleWithName', { name: d.profile.name });
  return DEFAULT_TITLES[getLang()];
};

// El system prompt de Joe's (en los 3 idiomas) está en joe-prompt.js.

// Busca un bloque \`\`\`routine ... \`\`\` en la respuesta y lo separa del texto para mostrar.
const extractRoutineProposal = (text) => {
  const match = text.match(/```routine\s*([\s\S]*?)```/);
  if (match) {
    const cleanText = (text.slice(0, match.index) + text.slice(match.index + match[0].length)).trim();
    try {
      const parsed = JSON.parse(match[1]);
      return { cleanText, proposal: parsed };
    } catch (e) {
      // El bloque cerró pero el JSON de adentro quedó roto (probablemente cortado a mitad).
      const cleanBefore = text.slice(0, match.index).trim();
      return { cleanText: cleanBefore || tr('truncatedRoutine'), proposal: null };
    }
  }
  // Abrió el bloque de rutina pero la respuesta se cortó antes de cerrarlo: no mostramos
  // el JSON a medio escribir como si fuera texto normal, avisamos y listo.
  const openMatch = text.match(/```routine([\s\S]*)$/);
  if (openMatch) {
    const cleanBefore = text.slice(0, openMatch.index).trim();
    return { cleanText: cleanBefore || tr('truncatedRoutine'), proposal: null };
  }
  return { cleanText: text, proposal: null };
};

// Busca un bloque \`\`\`exercise-lookup ... \`\`\` (pedido de Joe's de consultar un ejercicio puntual).
const extractExerciseLookupQuery = (text) => {
  const match = text.match(/```exercise-lookup\s*([\s\S]*?)```/);
  if (!match) return { cleanText: text, query: null };
  const cleanText = (text.slice(0, match.index) + text.slice(match.index + match[0].length)).trim();
  try {
    const parsed = JSON.parse(match[1]);
    return { cleanText, query: parsed.query || null };
  } catch (e) {
    return { cleanText, query: null };
  }
};

// Error de la IA con un "tipo" para poder mostrarle al usuario un mensaje que entienda.
// kind: 'model' (modelo retirado o inexistente), 'auth' (key inválida), 'rate' (límite gratis),
// 'too-large' (pedido muy grande), 'region' (servicio no disponible en el país),
// 'blocked' (el servicio no quiso responder), 'empty' (respuesta vacía), 'network', 'other'.
class AiError extends Error {
  constructor(kind, message, status) {
    super(message);
    this.kind = kind;
    this.status = status;
  }
}

// Reconoce de qué servicio es la key por cómo empieza. Si algún servicio cambia el formato de
// sus keys, alcanza con ajustar esto.
const detectAiProvider = (key) => {
  const k = (key || '').trim();
  if (/^gsk_/.test(k)) return 'groq';
  if (/^AIza/.test(k)) return 'gemini';
  return null;
};

const fetchOrNetworkError = async (url, options) => {
  try {
    return await fetch(url, options);
  } catch (e) {
    throw new AiError('network', 'Sin conexión', 0);
  }
};

// Lee el modelo que la app aprendió a usar la última vez. Pasados 7 días se ignora y se
// vuelve a probar el preferido.
const getRememberedModel = async (storageKey) => {
  try {
    const result = await storage.get(storageKey);
    if (!result || !result.value) return null;
    const saved = JSON.parse(result.value);
    if (!saved.model || Date.now() - (saved.savedAt || 0) > MODEL_RECHECK_MS) return null;
    return saved.model;
  } catch (e) {
    return null;
  }
};

const rememberModel = (storageKey, model) => storage
  .set(storageKey, JSON.stringify({ model, savedAt: Date.now() }))
  .catch(() => {});

// ----- Groq (formato compatible con OpenAI) -----

const classifyGroqError = (status, code, message) => {
  const msg = message || '';
  if (status === 401) return 'auth';
  if (status === 413 || code === 'request_too_large') return 'too-large';
  if (status === 429) {
    // "Limit 8000, Used 0, Requested 9500": el pedido solo ya supera el límite, esperar no sirve.
    const limits = msg.match(/Limit (\d+)[\s\S]*?Requested (\d+)/i);
    if (limits && Number(limits[2]) > Number(limits[1])) return 'too-large';
    return 'rate';
  }
  if (code === 'model_decommissioned' || code === 'model_not_found') return 'model';
  if ([400, 403, 404].includes(status) && /model/i.test(msg)
    && /decommission|does not exist|not found|no longer|not supported|deprecat|not available|do not have access|blocked/i.test(msg)) {
    return 'model';
  }
  return 'other';
};

// Elige el mejor modelo de chat de la lista que devuelve Groq: primero los preferidos (en
// orden), y si no está ninguno, el más grande (según el "120b", "70b", etc. del nombre).
const pickGroqModel = (models, exclude = []) => {
  const usable = models
    .filter((m) => m && typeof m.id === 'string' && m.active !== false)
    .map((m) => m.id)
    .filter((id) => !exclude.includes(id) && !GROQ_NON_CHAT_PATTERN.test(id));
  const preferred = GROQ_PREFERRED_MODELS.find((id) => usable.includes(id));
  if (preferred) return preferred;
  const sizeOf = (id) => {
    const sizes = [...id.matchAll(/(\d+(?:\.\d+)?)b(?![a-z])/gi)].map((x) => parseFloat(x[1]));
    return sizes.length ? Math.max(...sizes) : 0;
  };
  return usable.sort((a, b) => sizeOf(b) - sizeOf(a))[0] || null;
};

const findReplacementGroqModel = async (apiKey, tried) => {
  try {
    const res = await fetch(`${GROQ_BASE_URL}/models`, { headers: { Authorization: `Bearer ${apiKey}` } });
    if (res.ok) {
      const json = await res.json();
      const pick = pickGroqModel(json.data || [], tried);
      if (pick) return pick;
    }
  } catch (e) {
    // si no se pudo leer la lista, probamos a ciegas con los preferidos
  }
  return GROQ_PREFERRED_MODELS.find((id) => !tried.includes(id)) || null;
};

const requestGroqChat = async (apiKey, model, messages) => {
  const body = { model, messages, temperature: 0.7, max_completion_tokens: 4096 };
  // Los gpt-oss "piensan" antes de responder. Con esfuerzo bajo contestan rápido y no se
  // gastan el límite de tokens pensando (lo que cortaría las rutinas largas a la mitad).
  if (/gpt-oss/i.test(model)) {
    body.reasoning_effort = 'low';
    body.include_reasoning = false;
  }
  const res = await fetchOrNetworkError(`${GROQ_BASE_URL}/chat/completions`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    let message = '';
    let code = '';
    try {
      const err = (await res.json()).error || {};
      message = err.message || '';
      code = err.code || '';
    } catch (e) { /* noop */ }
    throw new AiError(classifyGroqError(res.status, code, message), message || `Error ${res.status}`, res.status);
  }
  const json = await res.json();
  // Algunos modelos (ej. Qwen) meten su "pensamiento" entre <think></think>; no se muestra.
  const content = (json.choices?.[0]?.message?.content || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  if (!content) throw new AiError('empty', 'Respuesta vacía', res.status);
  return content;
};

// ----- Google Gemini (API nativa, que acepta llamadas directas desde el navegador) -----

const classifyGeminiError = (status, statusText, message, reasons) => {
  const msg = message || '';
  if (reasons.includes('API_KEY_INVALID') || /api key not valid|api_key_invalid|api key expired/i.test(msg)) return 'auth';
  if (status === 401 || status === 403) return 'auth';
  if (status === 429 || statusText === 'RESOURCE_EXHAUSTED') return 'rate';
  if (/location is not supported|not available in your (country|region)/i.test(msg)) return 'region';
  if (status === 413 || /exceeds the maximum number of tokens|too large/i.test(msg)) return 'too-large';
  if (status === 404 || (/models\//i.test(msg) && /not found|not supported|deprecat|no longer/i.test(msg))) return 'model';
  return 'other';
};

// Elige el mejor modelo de la lista de Gemini: primero los preferidos, si no el Flash-Lite
// estable más nuevo, y si no el Flash estable más nuevo.
const pickGeminiModel = (models, exclude = []) => {
  const usable = models
    .filter((m) => m && typeof m.name === 'string' && (m.supportedGenerationMethods || []).includes('generateContent'))
    .map((m) => m.name.replace(/^models\//, ''))
    .filter((id) => /^gemini-/.test(id) && !exclude.includes(id));
  const preferred = GEMINI_PREFERRED_MODELS.find((id) => usable.includes(id));
  if (preferred) return preferred;
  const rank = (id) => (/flash-lite/.test(id) ? 2 : /flash/.test(id) ? 1 : 0);
  const version = (id) => parseFloat((id.match(/^gemini-(\d+(?:\.\d+)?)/) || [])[1] || '0');
  return usable
    .filter((id) => rank(id) > 0 && !GEMINI_NON_CHAT_PATTERN.test(id))
    .sort((a, b) => rank(b) - rank(a) || version(b) - version(a))[0] || null;
};

const findReplacementGeminiModel = async (apiKey, tried) => {
  try {
    const res = await fetch(`${GEMINI_BASE_URL}/models?pageSize=1000`, { headers: { 'x-goog-api-key': apiKey } });
    if (res.ok) {
      const json = await res.json();
      const pick = pickGeminiModel(json.models || [], tried);
      if (pick) return pick;
    }
  } catch (e) {
    // si no se pudo leer la lista, probamos a ciegas con los preferidos
  }
  return GEMINI_PREFERRED_MODELS.find((id) => !tried.includes(id)) || null;
};

// Pasa el historial del formato OpenAI (system/user/assistant) al de Gemini: el system va
// aparte, "assistant" se llama "model", y la charla tiene que arrancar con el usuario y
// alternar turnos (si hay dos mensajes seguidos del mismo lado, se juntan).
const toGeminiContents = (messages) => {
  const contents = [];
  messages.filter((m) => m.role !== 'system' && m.content).forEach((m) => {
    const role = m.role === 'assistant' ? 'model' : 'user';
    const last = contents[contents.length - 1];
    if (last && last.role === role) {
      last.parts[0].text += `\n\n${m.content}`;
    } else {
      contents.push({ role, parts: [{ text: m.content }] });
    }
  });
  while (contents.length && contents[0].role !== 'user') contents.shift();
  return contents;
};

const requestGeminiChat = async (apiKey, model, messages) => {
  const systemText = messages.filter((m) => m.role === 'system').map((m) => m.content).join('\n\n');
  const body = {
    contents: toGeminiContents(messages),
    // Margen amplio porque los Gemini nuevos "piensan" antes de responder y eso también cuenta.
    generationConfig: { maxOutputTokens: 8192 },
  };
  if (systemText) body.systemInstruction = { parts: [{ text: systemText }] };
  const res = await fetchOrNetworkError(`${GEMINI_BASE_URL}/models/${encodeURIComponent(model)}:generateContent`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-goog-api-key': apiKey,
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    let message = '';
    let statusText = '';
    let reasons = [];
    try {
      const err = (await res.json()).error || {};
      message = err.message || '';
      statusText = err.status || '';
      reasons = (err.details || []).map((d) => d && d.reason).filter(Boolean);
    } catch (e) { /* noop */ }
    throw new AiError(classifyGeminiError(res.status, statusText, message, reasons), message || `Error ${res.status}`, res.status);
  }
  const json = await res.json();
  const candidate = json.candidates?.[0];
  const text = (candidate?.content?.parts || [])
    .filter((p) => p && !p.thought && typeof p.text === 'string')
    .map((p) => p.text)
    .join('')
    .trim();
  if (!text) {
    const blocked = json.promptFeedback?.blockReason
      || ['SAFETY', 'PROHIBITED_CONTENT', 'BLOCKLIST', 'SPII', 'RECITATION'].includes(candidate?.finishReason);
    throw new AiError(blocked ? 'blocked' : 'empty', 'Respuesta vacía', res.status);
  }
  return text;
};

// ----- Lo que usa la app -----

const AI_PROVIDERS = {
  groq: {
    label: 'Groq',
    preferred: GROQ_PREFERRED_MODELS,
    modelStorage: 'groq-model-v1',
    request: requestGroqChat,
    findReplacement: findReplacementGroqModel,
  },
  gemini: {
    label: 'Gemini',
    preferred: GEMINI_PREFERRED_MODELS,
    modelStorage: 'gemini-model-v1',
    request: requestGeminiChat,
    findReplacement: findReplacementGeminiModel,
  },
};

// Habla con la IA que corresponda según la key. Si el modelo fue retirado busca otro y lo
// recuerda; si se llegó al límite gratis de un modelo prueba con el otro. Todo sin que el
// usuario se entere, salvo que no quede ninguna opción.
const callAi = async (apiKey, messages) => {
  const provider = AI_PROVIDERS[detectAiProvider(apiKey) || 'groq'];
  let model = (await getRememberedModel(provider.modelStorage)) || provider.preferred[0];
  const tried = [];
  let lastError = null;
  let modelWasRetired = false;
  for (let attempt = 0; attempt < 3 && model; attempt += 1) {
    try {
      // eslint-disable-next-line no-await-in-loop
      const reply = await provider.request(apiKey, model, messages);
      if (modelWasRetired) rememberModel(provider.modelStorage, model);
      return reply;
    } catch (e) {
      if (e.kind !== 'model' && e.kind !== 'rate') throw e;
      lastError = e;
      tried.push(model);
      if (e.kind === 'model') {
        modelWasRetired = true;
        // eslint-disable-next-line no-await-in-loop
        model = await provider.findReplacement(apiKey, tried);
      } else {
        model = provider.preferred.find((id) => !tried.includes(id)) || null;
      }
    }
  }
  throw lastError || new AiError('model', 'Sin modelos disponibles', 0);
};

const aiErrorMessage = (e, apiKey) => {
  const name = AI_PROVIDERS[detectAiProvider(apiKey) || 'groq'].label;
  const other = name === 'Groq' ? 'Gemini' : 'Groq';
  switch (e && e.kind) {
    case 'auth': return tr('aiErrAuth', { name });
    case 'rate': return tr('aiErrRate', { name });
    case 'too-large': return tr('aiErrTooLarge', { name });
    case 'region': return tr('aiErrRegion', { name, other });
    case 'blocked': return tr('aiErrBlocked');
    case 'empty': return tr('aiErrEmpty');
    case 'network': return tr('aiErrNetwork');
    case 'model': return tr('aiErrModel', { name });
    default: return tr('aiErrOther', { msg: (e && e.message) || 'error' });
  }
};

// La app muestra el texto tal cual (sin interpretar markdown), así que sacamos los ** y #
// que a veces mete el modelo para que no aparezcan como símbolos sueltos.
const toPlainChatText = (text) => (text || '')
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/__(.+?)__/g, '$1')
  .replace(/^#{1,6}\s+/gm, '')
  .trim();

// ---------- Código de sincronización ----------
// Llama a las funciones serverless en /api (necesitan Vercel KV configurado del lado del
// proyecto real; dentro del artifact de Claude estas llamadas van a fallar silenciosamente
// y la app sigue funcionando 100% local, como siempre).

const requestGenerateCode = async () => {
  const res = await fetch('/api/sync-generate', { method: 'POST' });
  if (!res.ok) {
    let detail = '';
    try { detail = (await res.json()).error || ''; } catch (e) { /* noop */ }
    throw new Error(detail || `Error ${res.status}`);
  }
  const json = await res.json();
  return json.code;
};

const fetchSyncData = async (code) => {
  const res = await fetch(`/api/sync-get?code=${encodeURIComponent(code)}`);
  if (res.status === 404) return null;
  if (!res.ok) {
    let detail = '';
    try { detail = (await res.json()).error || ''; } catch (e) { /* noop */ }
    throw new Error(detail || `Error ${res.status}`);
  }
  return res.json();
};

const pushSyncData = async (code, data, apiKey) => {
  const res = await fetch('/api/sync-save', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ code, data, apiKey: apiKey || '' }),
  });
  if (!res.ok) {
    let detail = '';
    try { detail = (await res.json()).error || ''; } catch (e) { /* noop */ }
    throw new Error(detail || `Error ${res.status}`);
  }
  return res.json();
};

