// ---------- Día ----------

// Línea chica debajo del nombre del ejercicio: lo anotado hoy, o lo de la vez pasada.
const exerciseInfo = (e, lifts) => {
  const log = currentLog(e);
  const done = log ? log.sets.filter((x) => x.done) : [];
  if (log && done.length) {
    const best = done.reduce((a, b) => ((parseFloat(String(b.kg).replace(',', '.')) || 0) > (parseFloat(String(a.kg).replace(',', '.')) || 0) ? b : a));
    return { kind: 'session', text: `${tr('setsProgress', { done: done.length, total: log.sets.length })} · ${formatSet(best)}` };
  }
  const prev = lastSession(lifts, e.name, log ? log.id : null);
  if (prev) {
    const top = prev.sets.reduce((a, b) => ((parseFloat(String(b.kg).replace(',', '.')) || 0) > (parseFloat(String(a.kg).replace(',', '.')) || 0) ? b : a));
    return { kind: 'last', text: tr('lastTimeShort', { set: formatSet(top) }) };
  }
  return null;
};

function DayCard({ day: d, lifts, editMode, onUpdateDay, onDeleteDay, onWeekdayChange, onOpenExercise, onAddExercise, onEditExercise, onShareDay, requestConfirm, usedWeekdays, usedPhrases, setNodeRef, justMoved }) {
  const [collapsed, setCollapsed] = useState(false);
  // Borrador del nombre del día: deja borrarlo entero para escribir otro (antes volvía a aparecer el de siempre).
  const [nameDraft, setNameDraft] = useState(null);
  const [weekdayMenuOpen, setWeekdayMenuOpen] = useState(false);
  const exNodesRef = useRef({});
  const dragExRef = useRef(null);
  const [dragExKey, setDragExKey] = useState(null);
  const [overExKey, setOverExKey] = useState(null);

  const colors = FOCUS_COLORS[d.focusKey] || FOCUS_COLORS.comodin;
  const list = d.list || [];
  const tagLabel = d.tagLabel || translateTag(colors.label, getLang());
  const isComplete = list.length > 0 && list.every((e) => e.done);
  const phrases = MOTIVATIONAL_PHRASES[getLang()];

  useLayoutEffect(() => {
    if (isComplete && !d.completionPhrase) {
      const available = phrases.filter((p) => !usedPhrases.has(p));
      const pool = available.length > 0 ? available : phrases;
      const phrase = pool[Math.floor(Math.random() * pool.length)];
      onUpdateDay({ ...d, completionPhrase: phrase });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isComplete]);

  const setList = (next) => onUpdateDay({ ...d, list: next });

  const toggleDone = (idx) => {
    const next = [...list];
    next[idx] = { ...next[idx], done: !next[idx].done };
    setList(next);
  };

  // Al completar el día se apaga el descanso que esté corriendo (el entrenamiento terminó).
  const wasCompleteRef = useRef(isComplete);
  useEffect(() => {
    if (isComplete && !wasCompleteRef.current && !editMode && restTimer.get().running) restTimer.stop();
    wasCompleteRef.current = isComplete;
  }, [isComplete, editMode]);

  const onExPointerDown = makePointerReorder({
    nodesRef: exNodesRef,
    dragRef: dragExRef,
    setDragKey: setDragExKey,
    setOverKey: setOverExKey,
    onDrop: (fromKey, toKey) => setList(reorder(list, Number(fromKey), Number(toKey))),
  });

  return (
    <div
      ref={setNodeRef}
      className={`day-card ${editMode ? 'day-card-editing' : ''} ${justMoved ? 'day-card-justmoved' : ''}`}
      style={{ '--accent': colors.accent, '--accent-bg': colors.bg }}
    >
      <div className="day-header">
        <div className="day-header-left">
          <div className="weekday-wrap">
            <button
              className={`focus-chip ${!editMode ? 'static' : 'focus-chip-edit'}`}
              onClick={() => editMode && setWeekdayMenuOpen((o) => !o)}
              aria-label={editMode ? tr('chooseWeekday') : undefined}
            >
              {weekdayLabel(d.weekday, getLang())}
              {editMode && <ChevronDown size={12} />}
            </button>
            {editMode && weekdayMenuOpen && (
              <>
                <div className="menu-backdrop" onClick={() => setWeekdayMenuOpen(false)} />
                <div className="weekday-menu">
                  {WEEK_DAYS.map((wd) => (
                    <button
                      key={wd}
                      className={`weekday-option ${wd === d.weekday ? 'current' : ''}`}
                      onClick={() => { onWeekdayChange(wd); setWeekdayMenuOpen(false); }}
                    >
                      {weekdayLabel(wd, getLang())}
                      {usedWeekdays.has(wd) && wd !== d.weekday && <span className="weekday-taken">{tr('weekdayTaken')}</span>}
                    </button>
                  ))}
                </div>
              </>
            )}
          </div>
          <div className="day-titles">
            {editMode ? (
              <input
                className="day-name-input"
                value={nameDraft != null ? nameDraft : tagLabel}
                onFocus={() => setNameDraft(tagLabel)}
                onChange={(e) => {
                  setNameDraft(e.target.value);
                  if (e.target.value.trim()) onUpdateDay({ ...d, tagLabel: e.target.value });
                }}
                onBlur={() => setNameDraft(null)}
                onKeyDown={(e) => { if (e.key === 'Enter') e.currentTarget.blur(); }}
                placeholder={tr('focusPlaceholder')}
                enterKeyHint="done"
              />
            ) : (
              <span className="day-name-static">{tagLabel}</span>
            )}
          </div>
        </div>
        <div className="day-header-right">
          <button className="icon-btn" onClick={() => setCollapsed(!collapsed)} aria-label={tr('collapse')}>
            {collapsed ? <ChevronDown size={16} /> : <ChevronUp size={16} />}
          </button>
          {editMode && (
            <button
              className="icon-btn danger"
              onClick={() => requestConfirm(tr('confirmDeleteDay', { day: weekdayLabel(d.weekday, getLang()) }), onDeleteDay)}
              aria-label={tr('deleteDay')}
            >
              <Trash2 size={15} />
            </button>
          )}
        </div>
      </div>

      {!collapsed && (
        <>
          <div className="ex-list">
            {list.length === 0 && <div className="empty-hint">{tr('noExercisesYet')}</div>}
            {list.map((exercise, idx) => (
              <ExerciseRow
                key={exercise.id}
                exercise={exercise}
                info={editMode ? null : exerciseInfo(exercise, lifts)}
                onOpen={() => onOpenExercise(exercise.id)}
                onEdit={() => onEditExercise(exercise.id)}
                editMode={editMode}
                onToggleDone={() => toggleDone(idx)}
                setNodeRef={(node) => {
                  if (node) exNodesRef.current[String(idx)] = node;
                  else delete exNodesRef.current[String(idx)];
                }}
                onHandlePointerDown={onExPointerDown(String(idx))}
                isDragging={dragExKey === String(idx)}
                isOver={overExKey === String(idx) && dragExKey !== String(idx)}
              />
            ))}
          </div>
          <button type="button" className={`add-ex-btn ${editMode ? 'add-ex-btn-edit' : ''}`} onClick={onAddExercise}>
            <Plus size={15} /> {tr('addExerciseRow')}
          </button>
          {isComplete && (
            <div className="day-congrats">
              <CheckCircle2 size={15} />
              <span>{phraseLabel(d.completionPhrase || phrases[0], getLang())}</span>
              {onShareDay && !editMode && (
                <button type="button" className="day-congrats-share" onClick={onShareDay}>
                  <Share2 size={13} /> {tr('shareStoryShort')}
                </button>
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ---------- Pestaña de rutina ----------

function VariantTab({ variant, active, editMode, canDelete, onSelect, onRename, onDuplicate, onDelete, setNodeRef, onHandlePointerDown, isDragging, isOver }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(variant.name);

  const save = () => {
    onRename(draft.trim() || variant.name);
    setEditing(false);
  };

  if (editMode && editing) {
    return (
      <input
        className="variant-name-input"
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={save}
        onKeyDown={(e) => { if (e.key === 'Enter') save(); if (e.key === 'Escape') setEditing(false); }}
        autoFocus
        style={{ background: variant.color }}
      />
    );
  }

  return (
    <div
      ref={editMode ? setNodeRef : undefined}
      className={`variant-btn-wrap ${active ? 'active' : ''} ${isDragging ? 'variant-btn-dragging' : ''} ${isOver ? 'variant-btn-over' : ''}`}
      style={{ '--variant-color': variant.color }}
    >
      {editMode && (
        <span className="variant-drag-handle" aria-hidden="true" onPointerDown={onHandlePointerDown}>
          <GripVertical size={11} />
        </span>
      )}
      <button className="variant-btn" onClick={onSelect} onDoubleClick={() => editMode && setEditing(true)} role="tab" aria-selected={active}>
        {variant.name}
      </button>
      {editMode && active && (
        <span className="variant-btn-actions">
          <button className="variant-mini-btn" onClick={() => setEditing(true)} aria-label={tr('renameRoutine')}><Pencil size={11} /></button>
          <button className="variant-mini-btn" onClick={onDuplicate} aria-label={tr('duplicateRoutine')}><Copy size={11} /></button>
          {canDelete && <button className="variant-mini-btn" onClick={onDelete} aria-label={tr('deleteRoutine')}><X size={11} /></button>}
        </span>
      )}
    </div>
  );
}

