function FloatingTimer({ raised }) {
  const [open, setOpen] = useState(false);
  const { remaining, running, justFinished, lastPreset } = useRestTimer();
  const isDefault = remaining === lastPreset && !running;

  return (
    <div className={`timer-wrap ${raised ? 'timer-wrap-raised' : ''}`}>
      {open && (
        <>
          <div className="menu-backdrop" onClick={() => setOpen(false)} />
          <div className="timer-panel">
            <div className="timer-panel-header">
              <span>{tr('rest')}</span>
              <button className="icon-btn" onClick={() => setOpen(false)} aria-label={tr('close')}><X size={14} /></button>
            </div>
            <div className="timer-display">{formatTime(remaining)}</div>
            <div className="timer-presets">
              {TIMER_PRESETS.map((s) => (
                <button
                  key={s}
                  className={`timer-preset-btn ${remaining === s && !running ? 'active' : ''} ${s === lastPreset ? 'is-last-used' : ''}`}
                  onClick={() => restTimer.setPreset(s)}
                  title={s === lastPreset ? tr('presetHint') : undefined}
                >
                  {s}s
                </button>
              ))}
            </div>
            <div className="timer-controls">
              <button className="timer-adjust-btn" onClick={() => restTimer.adjust(-10)}>-10s</button>
              <button className="timer-main-btn" onClick={() => restTimer.toggle()} aria-label={running ? tr('pause') : tr('start')}>
                {running ? <Pause size={18} /> : <Play size={18} />}
              </button>
              <button className="timer-adjust-btn" onClick={() => restTimer.adjust(10)}>+10s</button>
            </div>
            <button className="timer-reset-btn" onClick={() => restTimer.reset()}>
              <RotateCcw size={12} /> {tr('reset')}
            </button>
            <p className="timer-auto-hint">{tr('timerAutoHint')}</p>
          </div>
        </>
      )}
      <button
        className={`timer-fab ${justFinished ? 'timer-fab-alert' : ''} ${running ? 'timer-fab-running' : ''} ${!isDefault ? 'timer-fab-with-time' : ''}`}
        onClick={() => setOpen(!open)}
        aria-label={tr('restTimer')}
      >
        <Timer size={20} />
        {!isDefault && <span className="timer-fab-time">{formatTime(remaining)}</span>}
      </button>
    </div>
  );
}

