// ---------- Activar entrenador con IA (API key de Groq o de Gemini) ----------

function ApiKeySetup({ onActivate, onSkip, onRemove, initialKey }) {
  const [key, setKey] = useState('');
  const [keyError, setKeyError] = useState('');
  const currentProvider = detectAiProvider(initialKey);
  const [guide, setGuide] = useState(currentProvider || 'groq');

  const handleActivate = () => {
    const trimmed = key.trim();
    if (!trimmed) return;
    if (!detectAiProvider(trimmed)) {
      setKeyError(tr('akInvalid'));
      return;
    }
    setKeyError('');
    onActivate(trimmed);
  };

  return (
    <div className="apikey-screen">
      <div className="apikey-icon"><KeyRound size={26} /></div>
      <h1>{tr('akTitle')}</h1>
      <p>{rich(tr('akIntro'))}</p>
      {currentProvider && (
        <p className="apikey-current">{rich(tr('akCurrent', { provider: AI_PROVIDERS[currentProvider].label }))}</p>
      )}

      <div className="apikey-provider-toggle" role="tablist">
        <button
          role="tab"
          aria-selected={guide === 'groq'}
          className={guide === 'groq' ? 'active' : ''}
          onClick={() => setGuide('groq')}
        >
          Groq <span className="apikey-provider-tag">{tr('akRecommended')}</span>
        </button>
        <button
          role="tab"
          aria-selected={guide === 'gemini'}
          className={guide === 'gemini' ? 'active' : ''}
          onClick={() => setGuide('gemini')}
        >
          Gemini
        </button>
      </div>

      {guide === 'groq' ? (
        <ol className="apikey-steps">
          <li>
            {tr('akGoTo')}{' '}
            <a href="https://console.groq.com/keys" target="_blank" rel="noopener noreferrer">
              console.groq.com/keys <ExternalLink size={12} style={{ verticalAlign: 'middle' }} />
            </a>
          </li>
          <li>{tr('akGroq2')}</li>
          <li>{tr('akGroq3')}</li>
          <li>{tr('akPaste')}</li>
        </ol>
      ) : (
        <>
          <ol className="apikey-steps">
            <li>
              {tr('akGoTo')}{' '}
              <a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">
                aistudio.google.com/apikey <ExternalLink size={12} style={{ verticalAlign: 'middle' }} />
              </a>
            </li>
            <li>{tr('akGemini2')}</li>
            <li>{tr('akGemini3')}</li>
            <li>{tr('akPaste')}</li>
          </ol>
          <p className="apikey-note">{tr('akGeminiNote')}</p>
        </>
      )}

      <input
        className="apikey-input"
        type="password"
        value={key}
        onChange={(e) => { setKey(e.target.value); setKeyError(''); }}
        placeholder={initialKey ? tr('akActivated') : guide === 'gemini' ? 'AIza...' : 'gsk_...'}
        autoComplete="off"
      />
      {keyError && <p className="apikey-error">{keyError}</p>}
      <button className="apikey-activate-btn" onClick={handleActivate} disabled={!key.trim()}>
        {tr('akActivate')}
      </button>
      {onSkip && <button className="apikey-skip-btn" onClick={onSkip}>{tr('akSkip')}</button>}
      {initialKey && onRemove && (
        <button className="apikey-remove-btn" onClick={onRemove}>{tr('akRemove')}</button>
      )}
    </div>
  );
}

