function ChatScreen({ messages, onSend, loading, error, onAddRoutine, onChangeKey, providerLabel, quickPrompts }) {
  const [input, setInput] = useState('');
  const listRef = useRef(null);

  useEffect(() => {
    if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
  }, [messages, loading]);

  const handleSend = () => {
    if (!input.trim() || loading) return;
    onSend(input.trim());
    setInput('');
  };

  return (
    <div className="chat-screen">
      <div className="chat-header">
        <img src={FAVICON_DATA_URI} alt="" className="chat-avatar" />
        <div className="chat-header-text">
          <h2>Joe's</h2>
          <p>{tr('chatSubtitle')}{providerLabel ? ` · ${tr('chatWith', { provider: providerLabel })}` : ''}</p>
        </div>
        <button className="icon-btn chat-settings-btn" onClick={onChangeKey} aria-label={tr('changeKey')}>
          <Settings size={16} />
        </button>
      </div>

      <div className="chat-messages" ref={listRef}>
        {messages.length === 0 && (
          <div className="chat-empty">
            <img src={FAVICON_DATA_URI} alt="" className="chat-empty-avatar" />
            <p>{tr('chatEmpty')}</p>
          </div>
        )}
        {messages.map((m) => (
          <div key={m.id} className={`chat-bubble-row ${m.role === 'user' ? 'from-user' : 'from-assistant'}`}>
            {m.role === 'assistant' && <img src={FAVICON_DATA_URI} alt="" className="chat-msg-avatar" />}
            <div className="chat-bubble">
              {m.content && <p>{m.content}</p>}
              {m.proposal && (
                <div className="routine-proposal-card">
                  <div className="routine-proposal-title">
                    <Dumbbell size={13} /> {m.proposal.name || tr('newRoutine')}
                  </div>
                  <div className="routine-proposal-days">
                    {(m.proposal.days || []).map((d, i) => (
                      <div key={i} className="routine-proposal-day-block">
                        <div className="routine-proposal-day-head">{weekdayLabel(d.weekday, getLang())} · {d.focus}</div>
                        <ul className="routine-proposal-ex-list">
                          {(d.exercises || []).map((e, j) => (
                            <li key={j}>
                              <span className="routine-proposal-ex-name">{e.name}</span>
                              <span className="routine-proposal-ex-sets">{e.sets}</span>
                            </li>
                          ))}
                        </ul>
                      </div>
                    ))}
                  </div>
                  {m.added ? (
                    <div className="routine-proposal-added"><Check size={13} /> {tr('addedToRoutines')}</div>
                  ) : (
                    <button className="routine-proposal-btn" onClick={() => onAddRoutine(m.id, m.proposal)}>
                      {tr('addToRoutines')}
                    </button>
                  )}
                </div>
              )}
              {m.exerciseQuery && (
                <div className="exercise-lookup-card">
                  {m.exerciseLoading && (
                    <div className="exercise-lookup-loading">
                      <Loader2 size={13} className="spin" /> {tr('searchingWger', { q: m.exerciseQuery })}
                    </div>
                  )}
                  {!m.exerciseLoading && m.exerciseError && (
                    <div className="exercise-lookup-fallback">
                      {tr('wgerFetchFail')}{' '}
                      <a href={wgerSearchUrl()} target="_blank" rel="noopener noreferrer">{tr('wgerSearchQuery', { q: m.exerciseQuery })}</a>
                    </div>
                  )}
                  {!m.exerciseLoading && !m.exerciseError && m.exerciseResult && (
                    <div className="exercise-lookup-result">
                      {m.exerciseResult.images[0] && (
                        <img src={m.exerciseResult.images[0]} alt={m.exerciseResult.name} className="exercise-lookup-image" />
                      )}
                      <div className="exercise-lookup-name">{m.exerciseResult.name}</div>
                      {m.exerciseResult.muscles.length > 0 && (
                        <div className="exercise-lookup-meta">{tr('muscles')}: {m.exerciseResult.muscles.join(', ')}</div>
                      )}
                      {m.exerciseResult.equipment.length > 0 && (
                        <div className="exercise-lookup-meta">{tr('equipment')}: {m.exerciseResult.equipment.join(', ')}</div>
                      )}
                      {m.exerciseResult.description && <p className="exercise-lookup-desc">{m.exerciseResult.description}</p>}
                      <div className="exercise-lookup-credit">{tr('wgerCredit')}</div>
                    </div>
                  )}
                  {!m.exerciseLoading && !m.exerciseError && !m.exerciseResult && (
                    <div className="exercise-lookup-fallback">
                      {tr('wgerNotFound', { q: m.exerciseQuery })}{' '}
                      <a href={wgerSearchUrl()} target="_blank" rel="noopener noreferrer">{tr('wgerSearchIt')}</a>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div className="chat-bubble-row from-assistant">
            <img src={FAVICON_DATA_URI} alt="" className="chat-msg-avatar" />
            <div className="chat-bubble chat-loading"><Loader2 size={14} className="spin" /> {tr('thinking')}</div>
          </div>
        )}
        {error && <div className="chat-error">{error}</div>}
      </div>

      {quickPrompts && quickPrompts.length > 0 && !loading && (
        <div className="chat-quick" role="group" aria-label={tr('quickPromptsAria')}>
          {quickPrompts.map((q) => (
            <button key={q.label} type="button" className="chat-quick-btn" onClick={() => onSend(q.text)}>
              {q.label}
            </button>
          ))}
        </div>
      )}
      <div className="chat-composer">
        <input
          className="chat-input"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder={tr('chatPlaceholder')}
        />
        <button className="chat-send-btn" onClick={handleSend} disabled={!input.trim() || loading} aria-label={tr('send')}>
          <Send size={16} />
        </button>
      </div>
    </div>
  );
}

